import { pack as footballPlayerStats } from './football-player-stats/pack.js';
import { pack as subjectShowcase } from './subject-showcase/pack.js';

/**
 * The pack registry (Ring 3a) — every data-driven video PRODUCT this repo can
 * render.
 *
 * ── PACK vs PROJECT ─────────────────────────────────────────────────────────
 * `projects/registry.js` lists films: one entry, one video, fixed content. A
 * pack is a template plus a data contract, from which unlimited videos are
 * generated by swapping the document. Conflating the two is what turns an
 * engine back into a folder of one-off Remotion projects.
 *
 * ── WHY AN EXPLICIT ARRAY, NOT A GLOB ───────────────────────────────────────
 * Same reason the project registry gives: Remotion bundles statically, so a
 * dynamic `import(path)` built from a directory listing resolves in Studio and
 * fails on a render farm. It is also greppable, which a glob is not.
 */
/** Real packs first — the reference pack is a worked example, not a product. */
export const PACKS = [footballPlayerStats, subjectShowcase];

export const packById = (id) => {
  const found = PACKS.find((pack) => pack.id === id);
  if (!found) {
    throw new Error(
      `Unknown pack "${id}". Known: ${PACKS.map((p) => p.id).join(', ')}. ` +
        'Add it to PACKS in src/packs/registry.js.',
    );
  }
  return found;
};

/** Every shipped document, flattened — the editor's subject list. */
export const allSamples = () =>
  PACKS.flatMap((pack) => pack.samples.map((doc) => ({ pack, doc })));

/**
 * The document a pack opens with. Packs are required to ship at least one
 * sample: a pack with no document cannot be previewed, which makes it
 * unreviewable, which is how a broken pack survives to a render.
 */
export const firstSample = (pack) => {
  if (!pack.samples?.length) {
    throw new Error(`Pack "${pack.id}" ships no sample documents.`);
  }
  return pack.samples[0];
};
